<?php require_once __DIR__.'/../config/config.php';
$u=require_role(['teacher']);$uid=$u['id'];if($_SERVER['REQUEST_METHOD']!=='POST')json_response(['success'=>false,'message'=>'Method không hợp lệ'],405);
$bank=trim($_POST['bank_name']??'');$account=trim($_POST['account_number']??'');$owner=trim($_POST['account_owner']??'');$old=db()->prepare('SELECT qr_image FROM payment_settings WHERE teacher_id=?');$old->execute([$uid]);$oldQr=$old->fetchColumn();$qr=$oldQr?:null;
if(isset($_FILES['qr_image'])&&$_FILES['qr_image']['error']!==UPLOAD_ERR_NO_FILE){if($_FILES['qr_image']['error']!==UPLOAD_ERR_OK||$_FILES['qr_image']['size']>3*1024*1024)json_response(['success'=>false,'message'=>'Ảnh QR tối đa 3MB.'],422);$finfo=new finfo(FILEINFO_MIME_TYPE);$mime=$finfo->file($_FILES['qr_image']['tmp_name']);$allowed=['image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp'];if(!isset($allowed[$mime]))json_response(['success'=>false,'message'=>'Chỉ hỗ trợ PNG, JPG hoặc WEBP.'],422);$dir=__DIR__.'/../uploads/qr';if(!is_dir($dir))mkdir($dir,0755,true);$name='qr_'.$uid.'_'.bin2hex(random_bytes(5)).'.'.$allowed[$mime];if(!move_uploaded_file($_FILES['qr_image']['tmp_name'],$dir.'/'.$name))json_response(['success'=>false,'message'=>'Không thể lưu ảnh QR.'],500);if($oldQr&&str_starts_with($oldQr,'uploads/qr/'))@unlink(__DIR__.'/../'.$oldQr);$qr='uploads/qr/'.$name;}
$st=db()->prepare('INSERT INTO payment_settings(teacher_id,bank_name,account_number,account_owner,qr_image) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE bank_name=VALUES(bank_name),account_number=VALUES(account_number),account_owner=VALUES(account_owner),qr_image=VALUES(qr_image)');$st->execute([$uid,$bank,$account,$owner,$qr]);json_response(['success'=>true]);
